('dph-pharmacology-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',2204,'{"question":"Absorption is movement of a drug","translation":"Absorption is movement of a drug","options":["From administration site into systemic circulation","From blood into urine only","From liver into bile only","Into the medicine pack"],"correctIndex":0,"explanation":"Absorption transfers a drug into systemic circulation from its administration site.","explanationNe":"औषधि दिएको स्थानबाट systemic circulation मा प्रवेश गर्नु absorption हो।"}'::jsonb,true),
('dph-pharmacology-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',2205,'{"question":"Distribution is movement of a drug","translation":"Distribution is movement of a drug","options":["Between blood and body tissues","Only into the stomach","Only out through urine","Into the package"],"correctIndex":0,"explanation":"Distribution is transfer of a drug between blood and tissues.","explanationNe":"रगत र शरीरका tissue बीच औषधिको आवागमन distribution हो।"}'::jsonb,true),
('dph-pharmacology-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',2206,'{"question":"The major organ for metabolism of many drugs is","translation":"The major organ for metabolism of many drugs is","options":["Liver","Hair","Nails","Teeth"],"correctIndex":0,"explanation":"The liver is the main metabolic organ for many medicines.","explanationNe":"धेरै औषधिको metabolism हुने मुख्य अंग कलेजो हो।"}'::jsonb,true),
('dph-pharmacology-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',2207,'{"question":"Many drugs are excreted mainly by the","translation":"Many drugs are excreted mainly by the","options":["Kidneys","Heart","Spleen","Skin"],"correctIndex":0,"explanation":"Kidneys eliminate many drugs and metabolites in urine.","explanationNe":"मिर्गौलाले धेरै औषधि तथा metabolites पिसाबबाट निकाल्छ।"}'::jsonb,true),
('dph-pharmacology-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',2208,'{"question":"Bioavailability is the fraction of drug reaching","translation":"Bioavailability is the fraction of drug reaching","options":["Systemic circulation unchanged","The skin surface only","The stomach contents only","The package"],"correctIndex":0,"explanation":"It describes the rate and extent active drug reaches systemic circulation.","explanationNe":"सक्रिय औषधि systemic circulation मा पुग्ने दर र मात्रा bioavailability हो।"}'::jsonb,true),
('dph-pharmacology-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',2209,'{"question":"Which route commonly avoids initial first-pass metabolism?","translation":"Which route commonly avoids initial first-pass metabolism?","options":["Sublingual","Swallowed oral tablet","Oral capsule","Oral syrup"],"correctIndex":0,"explanation":"Sublingual absorption enters systemic circulation without initial portal passage.","explanationNe":"Sublingual route ले सुरुमा portal circulation हुँदै कलेजोमा जानु पर्दैन।"}'::jsonb,true),
