('dph-pharmacology-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',2220,'{"question":"Additive effect means","translation":"Additive effect means","options":["Combined effect is approximately the sum of individual effects","Combined effect is always zero","Both drugs are inactive","Drug colour changes"],"correctIndex":0,"explanation":"Additive responses approximate the sum of separate effects.","explanationNe":"संयुक्त प्रभाव व्यक्तिगत प्रभावको योग बराबर हुन्छ।"}'::jsonb,true),
