('dph-pharmacology-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',2236,'{"question":"Dispensing errors can be reduced by checking","translation":"Dispensing errors can be reduced by checking","options":["Patient, drug, strength, dose and route","Package colour only","Brand advertisement","Shelf position only"],"correctIndex":0,"explanation":"Systematic verification reduces medication errors.","explanationNe":"बिरामी, औषधि, strength, dose र route जाँच्दा त्रुटि घट्छ।"}'::jsonb,true),
